import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { Link, Navigate, useLocation, useNavigate } from 'react-router-dom';
import {
  AppWindow, ArrowRight, Check, ChevronLeft, Fingerprint, Globe2, KeyRound,
  Loader2, LogOut, MonitorSmartphone, RefreshCw, Save, ShieldCheck, Trash2,
  Upload, UserRound,
} from 'lucide-react';
import { idAuth, uploadIdentityAvatar, type IdMe, type OAuthGrant } from '../lib/idAuth';
import type { WerseeIdentity } from '../lib/identity';

type IdentitySection = 'overview' | 'profile' | 'security' | 'passkeys' | 'sessions' | 'apps';
const sections: { id: IdentitySection; label: string; icon: typeof UserRound }[] = [
  { id: 'overview', label: 'Overview', icon: Globe2 }, { id: 'profile', label: 'Profile', icon: UserRound },
  { id: 'security', label: 'Security', icon: ShieldCheck }, { id: 'passkeys', label: 'Passkeys', icon: Fingerprint },
  { id: 'sessions', label: 'Sessions', icon: MonitorSmartphone }, { id: 'apps', label: 'Connected apps', icon: AppWindow },
];
const services = [
  ['Wersee', 'https://www.wersee.com/workspace'], ['App', 'https://app.wersee.com'],
  ['Community', 'https://community.wersee.com'], ['Pay', 'https://pay.wersee.com'],
  ['Email', 'https://email.wersee.com'], ['Chat', 'https://chat.wersee.com'],
  ['Gate', 'https://gate.wersee.com'], ['Files', 'https://files.wersee.com'],
];
const serviceUrl = (destination: string) => `/login?redirect=${encodeURIComponent(destination)}`;
const messageFrom = (error: unknown) => error instanceof Error ? error.message : 'Something went wrong.';
const inputClass = 'w-full rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm text-white outline-none transition focus:border-violet-400/50 focus:ring-4 focus:ring-violet-500/10';
const Card = ({ children, className = '' }: { children: ReactNode; className?: string }) => <section className={`rounded-[24px] border border-white/10 bg-white/[0.045] p-5 shadow-[0_20px_70px_rgba(0,0,0,0.22)] md:p-6 ${className}`}>{children}</section>;
const Notice = ({ error, children }: { error?: boolean; children: ReactNode }) => <div className={`rounded-2xl border px-4 py-3 text-sm ${error ? 'border-red-400/20 bg-red-400/10 text-red-200' : 'border-emerald-400/20 bg-emerald-400/10 text-emerald-200'}`}>{children}</div>;
const initials = (identity: WerseeIdentity) => (identity.display_name || identity.username || identity.email || 'W').split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase();

const Profile = ({ me, reload }: { me: IdMe; reload: () => Promise<void> }) => {
  const identity = me.identity;
  const [form, setForm] = useState({ display_name: identity.display_name || '', username: identity.username || '', email: identity.email || '', bio: identity.bio || '', locale: identity.locale, timezone: identity.timezone, currency: identity.currency });
  const [busy, setBusy] = useState(false); const [notice, setNotice] = useState<{ error?: boolean; text: string } | null>(null);
  const save = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setNotice(null);
    try {
      const result = await idAuth.updateProfile(form);
      setNotice({ text: result.email_change_pending ? 'Profile saved. Confirm the email change from your inbox.' : 'Your Wersee identity has been updated everywhere.' });
      await reload();
    } catch (error) { setNotice({ error: true, text: messageFrom(error) }); }
    finally { setBusy(false); }
  };
  const avatar = async (file?: File) => {
    if (!file) return; setBusy(true); setNotice(null);
    try { const avatar_url = await uploadIdentityAvatar(file); await idAuth.updateProfile({ avatar_url }); await reload(); setNotice({ text: 'Your new avatar is active across Wersee.' }); }
    catch (error) { setNotice({ error: true, text: messageFrom(error) }); }
    finally { setBusy(false); }
  };
  return <form onSubmit={save} className="space-y-5"><Card><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><div className="grid h-24 w-24 place-items-center overflow-hidden rounded-[28px] border border-white/10 bg-gradient-to-br from-violet-500/30 to-blue-500/20 text-2xl font-black">{identity.avatar_url ? <img src={identity.avatar_url} alt="" className="h-full w-full object-cover" /> : initials(identity)}</div><div><h2 className="text-lg font-bold">Wersee-wide avatar</h2><p className="mt-1 text-sm text-white/50">Owned by Wersee ID and synchronized to every connected service.</p><label className="mt-4 inline-flex cursor-pointer items-center gap-2 rounded-full border border-white/10 bg-white/10 px-4 py-2 text-xs font-semibold hover:bg-white/15"><Upload className="h-4 w-4" />Change avatar<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" className="hidden" disabled={busy} onChange={(event) => void avatar(event.target.files?.[0])} /></label></div></div></Card><Card className="space-y-5"><div><h2 className="text-lg font-bold">Profile and preferences</h2><p className="mt-1 text-sm text-white/50">One canonical profile for every Wersee product.</p></div><div className="grid gap-4 md:grid-cols-2"><label className="space-y-2 text-xs font-semibold text-white/60">Display name<input className={inputClass} required maxLength={160} value={form.display_name} onChange={(event) => setForm({ ...form, display_name: event.target.value })} /></label><label className="space-y-2 text-xs font-semibold text-white/60">Username<input className={inputClass} required minLength={3} maxLength={32} value={form.username} onChange={(event) => setForm({ ...form, username: event.target.value.toLowerCase() })} /></label><label className="space-y-2 text-xs font-semibold text-white/60 md:col-span-2">Email<input type="email" className={inputClass} required value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></label><label className="space-y-2 text-xs font-semibold text-white/60 md:col-span-2">Bio<textarea className={`${inputClass} min-h-24 resize-y`} maxLength={500} value={form.bio} onChange={(event) => setForm({ ...form, bio: event.target.value })} /></label><label className="space-y-2 text-xs font-semibold text-white/60">Language<select className={inputClass} value={form.locale} onChange={(event) => setForm({ ...form, locale: event.target.value })}><option value="en-US">English</option><option value="nl-NL">Nederlands</option><option value="de-DE">Deutsch</option><option value="fr-FR">Français</option></select></label><label className="space-y-2 text-xs font-semibold text-white/60">Timezone<input className={inputClass} value={form.timezone} onChange={(event) => setForm({ ...form, timezone: event.target.value })} /></label><label className="space-y-2 text-xs font-semibold text-white/60">Currency<select className={inputClass} value={form.currency} onChange={(event) => setForm({ ...form, currency: event.target.value })}><option>EUR</option><option>USD</option><option>GBP</option></select></label></div>{notice && <Notice error={notice.error}>{notice.text}</Notice>}<button disabled={busy} className="inline-flex items-center gap-2 rounded-full bg-white px-5 py-2.5 text-sm font-bold text-black disabled:opacity-50">{busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}Save identity</button></Card></form>;
};

const Security = ({ me, reload }: { me: IdMe; reload: () => Promise<void> }) => {
  const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState<{ error?: boolean; text: string } | null>(null);
  const [enrollment, setEnrollment] = useState<{ factorId: string; qr: string } | null>(null); const [code, setCode] = useState(''); const [challengeId, setChallengeId] = useState('');
  const changePassword = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setNotice(null); try { if (password !== confirm) throw new Error('The passwords do not match.'); await idAuth.resetPassword(password); setPassword(''); setConfirm(''); setNotice({ text: 'Password updated for your complete Wersee account.' }); } catch (error) { setNotice({ error: true, text: messageFrom(error) }); } finally { setBusy(false); } };
  const enroll = async () => { setBusy(true); setNotice(null); try { const data = await idAuth.mfaEnroll('Wersee Authenticator'); const challenge = await idAuth.mfaChallenge(data.factor_id); setEnrollment({ factorId: data.factor_id, qr: data.qr_code }); setChallengeId(challenge.challenge_id); } catch (error) { setNotice({ error: true, text: messageFrom(error) }); } finally { setBusy(false); } };
  const verify = async () => { if (!enrollment || !challengeId) return; setBusy(true); try { await idAuth.mfaVerify(enrollment.factorId, challengeId, code, 'https://id.wersee.com/security'); setEnrollment(null); setCode(''); await reload(); setNotice({ text: 'Two-factor authentication is now active.' }); } catch (error) { setNotice({ error: true, text: messageFrom(error) }); } finally { setBusy(false); } };
  const remove = async (id: string) => { if (!window.confirm('Remove this two-factor authenticator?')) return; setBusy(true); try { await idAuth.mfaRemove(id); await reload(); } catch (error) { setNotice({ error: true, text: messageFrom(error) }); } finally { setBusy(false); } };
  return <div className="space-y-5"><Card><div className="flex gap-4"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-emerald-400/10 text-emerald-300"><ShieldCheck className="h-5 w-5" /></span><div><h2 className="font-bold">Account security</h2><p className="mt-1 text-sm text-white/50">{me.user.email_verified ? 'Email verified' : 'Email verification required'} · Current assurance {me.assurance.currentLevel || 'unknown'}</p><div className="mt-3 flex flex-wrap gap-2">{me.user.identities.map((identity) => <span key={identity.id} className="rounded-full border border-white/10 bg-white/5 px-3 py-1 text-xs capitalize text-white/60">{identity.provider}</span>)}</div></div></div></Card><Card className="space-y-4"><div><h2 className="text-lg font-bold">Two-factor authentication</h2><p className="mt-1 text-sm text-white/50">Authenticator factors are enforced before sensitive account actions.</p></div>{me.factors.totp.length ? <div className="space-y-2">{me.factors.totp.map((factor) => <div key={factor.id} className="flex items-center justify-between rounded-2xl border border-white/10 bg-black/20 p-4"><div><p className="text-sm font-semibold">{factor.friendly_name || 'Authenticator app'}</p><p className="text-xs text-emerald-300">{factor.status || 'verified'}</p></div><button onClick={() => void remove(factor.id)} disabled={busy} className="rounded-full border border-red-400/20 bg-red-400/10 p-2 text-red-200"><Trash2 className="h-4 w-4" /></button></div>)}</div> : <button onClick={() => void enroll()} disabled={busy} className="rounded-full bg-white px-5 py-2.5 text-sm font-bold text-black">Enable authenticator app</button>}{enrollment && <div className="space-y-3 rounded-2xl border border-violet-400/20 bg-violet-400/5 p-4"><p className="text-sm font-semibold">Scan this one-time QR code, then verify the current code.</p><img src={enrollment.qr} alt="Authenticator enrollment QR code" className="mx-auto h-48 w-48 rounded-xl bg-white p-2" /><input className={`${inputClass} text-center tracking-[0.3em]`} inputMode="numeric" value={code} onChange={(event) => setCode(event.target.value.replace(/\D/g, '').slice(0, 10))} placeholder="000000" /><button onClick={() => void verify()} disabled={busy} className="w-full rounded-full bg-white px-5 py-2.5 text-sm font-bold text-black">Verify authenticator</button></div>}</Card><Card><form onSubmit={changePassword} className="max-w-xl space-y-4"><div><h2 className="text-lg font-bold">Change password</h2><p className="mt-1 text-sm text-white/50">Changes apply to every Wersee service.</p></div><input type="password" autoComplete="new-password" minLength={8} required placeholder="New password" className={inputClass} value={password} onChange={(event) => setPassword(event.target.value)} /><input type="password" autoComplete="new-password" minLength={8} required placeholder="Confirm new password" className={inputClass} value={confirm} onChange={(event) => setConfirm(event.target.value)} />{notice && <Notice error={notice.error}>{notice.text}</Notice>}<button disabled={busy} className="inline-flex items-center gap-2 rounded-full bg-white px-5 py-2.5 text-sm font-bold text-black disabled:opacity-50"><KeyRound className="h-4 w-4" />Update password</button></form></Card></div>;
};

const Apps = () => {
  const [grants, setGrants] = useState<OAuthGrant[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(null); try { setGrants((await idAuth.apps()).grants); } catch (nextError) { setError(messageFrom(nextError)); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  return <Card className="space-y-4"><div><h2 className="text-lg font-bold">Apps signed in with Wersee</h2><p className="mt-1 text-sm text-white/50">Review and revoke OAuth grants centrally.</p></div>{loading ? <Loader2 className="h-5 w-5 animate-spin" /> : error ? <Notice error>{error}</Notice> : grants.length ? grants.map((grant) => <div key={grant.client.id} className="flex flex-col gap-3 rounded-2xl border border-white/10 bg-black/20 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">{grant.client.name}</p><p className="text-xs text-white/40">{new URL(grant.client.uri).hostname} · {grant.scopes.join(', ')}</p></div><button onClick={() => void idAuth.revokeApp(grant.client.id).then(load).catch((nextError) => setError(messageFrom(nextError)))} className="rounded-full border border-red-400/20 bg-red-400/10 px-4 py-2 text-xs font-semibold text-red-200">Revoke</button></div>) : <p className="rounded-2xl border border-white/10 bg-black/20 p-5 text-sm text-white/45">No approved OAuth apps.</p>}</Card>;
};

export const WerseeIdCenter = () => {
  const location = useLocation(); const navigate = useNavigate(); const [me, setMe] = useState<IdMe | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState<string | null>(null);
  const section = (location.pathname.split('/').filter(Boolean)[1] || (location.pathname === '/security' ? 'security' : 'overview')) as IdentitySection;
  const active = sections.some((item) => item.id === section) ? section : 'overview';
  const load = useCallback(async () => { setLoading(true); setError(null); try { setMe(await idAuth.me()); } catch (nextError) { const status = (nextError as { status?: number }).status; if (status === 401) { const login = new URL('/login', window.location.origin); login.searchParams.set('redirect', window.location.href); window.location.replace(login.toString()); return; } setError(messageFrom(nextError)); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const title = useMemo(() => sections.find((item) => item.id === active)?.label || 'Overview', [active]);
  useEffect(() => { document.title = `${title} - Wersee ID`; }, [title]);
  if (location.pathname === '/' || location.pathname === '/account') return <Navigate to="/account/overview" replace />;
  if (loading || !me) return <div className="grid min-h-[100dvh] place-items-center bg-[#07070a] text-white">{error ? <div className="space-y-4 text-center"><Notice error>{error}</Notice><button onClick={() => void load()} className="rounded-full bg-white px-4 py-2 text-sm font-bold text-black">Retry</button></div> : <Loader2 className="h-6 w-6 animate-spin" />}</div>;
  const identity = me.identity;
  return <div className="min-h-[100dvh] bg-[#07070a] text-white"><div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_15%_0%,rgba(124,58,237,0.18),transparent_32%),radial-gradient(circle_at_85%_10%,rgba(37,99,235,0.13),transparent_30%)]" /><header className="sticky top-0 z-30 border-b border-white/10 bg-[#07070a]/80 backdrop-blur-2xl"><div className="mx-auto flex max-w-6xl items-center justify-between px-4 py-3 md:px-6"><Link to="/account/overview" className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-[13px] bg-white text-sm font-black text-black">W</span><div><p className="text-sm font-bold">Wersee ID</p><p className="text-[10px] text-white/40">One identity. Every Wersee service.</p></div></Link><a href={serviceUrl('https://www.wersee.com/workspace')} className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-2 text-xs font-semibold text-white/80">Open Wersee <ArrowRight className="h-3.5 w-3.5" /></a></div></header><div className="relative mx-auto grid max-w-6xl gap-6 px-4 py-6 md:grid-cols-[230px_minmax(0,1fr)] md:px-6 md:py-10"><aside className="md:sticky md:top-24 md:h-fit"><div className="mb-5 flex items-center gap-3 px-2"><div className="grid h-12 w-12 place-items-center overflow-hidden rounded-2xl border border-white/10 bg-white/10 font-bold">{identity.avatar_url ? <img src={identity.avatar_url} alt="" className="h-full w-full object-cover" /> : initials(identity)}</div><div className="min-w-0"><p className="truncate text-sm font-bold">{identity.display_name || identity.email}</p><p className="truncate text-xs text-white/40">{identity.username ? `@${identity.username}` : identity.email}</p></div></div><nav className="flex gap-2 overflow-x-auto pb-2 md:block md:space-y-1 md:overflow-visible">{sections.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => navigate(`/account/${id}`)} className={`flex shrink-0 items-center gap-3 rounded-full px-4 py-2.5 text-sm font-semibold transition md:w-full md:rounded-2xl ${active === id ? 'bg-white text-black' : 'text-white/55 hover:bg-white/5 hover:text-white'}`}><Icon className="h-4 w-4" />{label}</button>)}</nav></aside><main className="min-w-0"><div className="mb-6"><button onClick={() => navigate('/account/overview')} className={`mb-3 items-center gap-1 text-xs text-white/45 ${active === 'overview' ? 'hidden' : 'inline-flex'}`}><ChevronLeft className="h-3.5 w-3.5" />Account</button><h1 className="text-2xl font-black tracking-tight md:text-3xl">{title}</h1><p className="mt-2 text-sm text-white/45">Managed centrally by id.wersee.com</p></div>{active === 'overview' && <div className="space-y-5"><Card><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><div className="grid h-20 w-20 place-items-center overflow-hidden rounded-[25px] border border-white/10 bg-gradient-to-br from-violet-500/30 to-blue-500/20 text-xl font-black">{identity.avatar_url ? <img src={identity.avatar_url} alt="" className="h-full w-full object-cover" /> : initials(identity)}</div><div><h2 className="text-xl font-black">{identity.display_name || identity.email}</h2><p className="mt-1 text-sm text-white/45">{identity.email} · ID {identity.id}</p><span className="mt-3 inline-flex items-center gap-1.5 rounded-full bg-emerald-400/10 px-3 py-1 text-xs font-semibold text-emerald-300"><Check className="h-3 w-3" />Wersee ID active · {me.assurance.currentLevel}</span></div></div></Card><div className="grid gap-4 sm:grid-cols-2">{sections.slice(1).map(({ id, label, icon: Icon }) => <button key={id} onClick={() => navigate(`/account/${id}`)} className="rounded-[22px] border border-white/10 bg-white/[0.04] p-5 text-left hover:bg-white/[0.07]"><Icon className="h-5 w-5" /><h3 className="mt-5 font-bold">{label}</h3></button>)}</div><Card><h2 className="font-bold">Continue with Wersee</h2><p className="mt-1 text-sm text-white/45">Each product receives its own narrow session through the audited OAuth handoff.</p><div className="mt-4 flex flex-wrap gap-2">{services.map(([name, url]) => <a key={name} href={serviceUrl(url)} className="rounded-full border border-white/10 bg-white/5 px-4 py-2 text-xs font-semibold">{name}</a>)}</div></Card></div>}{active === 'profile' && <Profile me={me} reload={load} />}{active === 'security' && <Security me={me} reload={load} />}{active === 'passkeys' && <Card><Fingerprint className="h-7 w-7 text-violet-300" /><h2 className="mt-4 text-lg font-bold">Passkeys are staged safely</h2><p className="mt-2 text-sm leading-6 text-white/50">The UI and integration boundary are ready. Registration stays disabled until the Supabase WebAuthn RP ID and exact Wersee origins are production-verified.</p><span className="mt-4 inline-flex rounded-full bg-amber-400/10 px-3 py-1 text-xs font-semibold text-amber-200">Feature flag off</span></Card>}{active === 'sessions' && <Card className="space-y-4"><div className="flex gap-4"><MonitorSmartphone className="h-6 w-6 text-blue-300" /><div><h2 className="font-bold">This browser</h2><p className="text-sm text-white/50">Host-only HttpOnly Wersee ID session · active now</p></div></div><div className="flex flex-wrap gap-3"><button onClick={() => void idAuth.logout('others')} className="rounded-full border border-white/10 bg-white/5 px-4 py-2.5 text-sm font-semibold">Sign out other sessions</button><button onClick={() => void idAuth.logout('global').then(() => window.location.assign('/login'))} className="inline-flex items-center gap-2 rounded-full border border-red-400/20 bg-red-400/10 px-4 py-2.5 text-sm font-semibold text-red-200"><LogOut className="h-4 w-4" />Sign out everywhere</button></div></Card>}{active === 'apps' && <Apps />}</main></div></div>;
};
